dist = ROOT / "dist"
shutil.rmtree(dist, ignore_errors=True)
template = (ROOT / "frontend" / "template.html").read_text(encoding="utf-8")
for slug, lang, short, title in COURSES:
    target = dist / slug
    target.mkdir(parents=True)
    values = dict(COPY[lang], LANG=lang, TITLE=title, SHORT_TITLE=short)
    html = template
    for key, value in values.items():
        html = html.replace("{{" + key + "}}", value)
    (target / "index.html").write_text(html, encoding="utf-8")
    for asset in ("style.css", "app.js", "logo.png"):
        shutil.copy2(ROOT / "frontend" / asset, target / asset)
    config = {"slug": slug, "api": API, "locale": "kk-KZ" if lang == "kk" else "ru-RU", "copy": STATUS[lang], "reviews": COURSE_REVIEWS.get(slug, REVIEWS[lang])}
    (target / "config.js").write_text("window.SITE_CONFIG = " + json.dumps(config, ensure_ascii=False) + ";", encoding="utf-8")
